etapes.texte:
On additionne les solutions des deux morceaux, sans compter deux fois $x = 0$ :

- si $m < -1$ : aucune solution, car $-1$ est le minimum de $f$ ;
- si $m = -1$ : une seule solution, $x = 0$ ;
- si $-1 < m < 0$ : deux solutions, une dans $]-\infty\,;\,0[$ et une dans $]0\,;\,+\infty[$ ;
- si $m \geqslant 0$ : une seule solution, dans $]0\,;\,+\infty[$.

code.source:
def f(x):
    return x**3 + x - 1

def derivee(x):              # f'(x) = 3x² + 1
    return 3 * x**2 + 1

def newton(x, n):
    for k in range(n):
        x = x - f(x) / derivee(x)   # là où la tangente coupe l'axe
    return x

print(newton(1, 4))          # affiche 0.6823278039465127

def f(x):
    return x**3 + x - 1

def secante(a, b, n):
    for k in range(n):
        c = b - f(b) * (b - a) / (f(b) - f(a))   # là où la sécante coupe l'axe
        a = b
        b = c
    return b

print(secante(0, 1, 5))      # affiche 0.6823257814098928
